// ————— Review quizzes: the card at the top of a section, and the quiz —————
// HAND-MAINTAINED. Not generated by build-vite-app.py.
//
// The rules live in lib/placement.js; this file draws them. The card appears at
// the top of Hiragana, Katakana or Kanji only for a learner who said, in the
// first-visit wizard, that they wanted that section's review quiz (Lloyd,
// Oct 8 2026: "Top of each section").
//
// No romaji anywhere: kana questions are SPOKEN — the modules' own recorded
// sprite, falling back to the device's Japanese voice — and answered in kana;
// kanji questions give the English meaning and are answered in kanji.
//
// The colours are deliberate. Right is 緑, the app's "ok". A wrong pick is
// marked in ink, NOT 朱 — vermilion means FIX on the Checker, and a review quiz
// is not a correction.

import { useState, useEffect, useRef, useCallback } from "react";
import { T } from "./tokens.js";
import Dialog from "./dialog.jsx";
import {
  SECTIONS, QUIZ, passMark, buildQuestions, readPlacement, quizStatus,
  sectionOffered, recordAttempt, LOCK_DAYS,
} from "./placement.js";

const fmtDay = (ts) => new Date(ts).toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric" });
const LABEL = { font: `700 0.6875rem ${T.uiFont}`, letterSpacing: ".08em", color: T.muted };
const body = { margin: 0, font: `0.875rem/1.6 ${T.uiFont}`, color: T.sub };

// ————— Audio: the kana modules' sprite, loaded once —————
let actx = null, abuf = null, amap = null, aload = null;
function loadSprite() {
  if (aload) return aload;
  aload = (async () => {
    const AC = typeof window !== "undefined" && (window.AudioContext || window.webkitAudioContext);
    if (!AC) return false;
    const [spec, audio] = await Promise.all([fetch("./audio/kana-sprite.json"), fetch("./audio/kana-sprite.mp3")]);
    if (!spec.ok || !audio.ok) return false;
    const clips = (await spec.json()).clips;
    actx = new AC();
    abuf = await actx.decodeAudioData(await audio.arrayBuffer());
    amap = clips;
    return true;
  })().catch(() => false);
  return aload;
}
function say(item) {
  if (actx && abuf && amap && amap[item.sound]) {
    if (actx.state === "suspended") actx.resume();
    const src = actx.createBufferSource();
    src.buffer = abuf; src.connect(actx.destination);
    const [at, dur] = amap[item.sound];
    src.start(0, at, dur);
    return;
  }
  // No recording for this sound (ヴ): the device's Japanese voice says the kana.
  try {
    const u = new SpeechSynthesisUtterance(item.q);
    u.lang = "ja-JP";
    window.speechSynthesis.cancel();
    window.speechSynthesis.speak(u);
  } catch { /* nothing to play it with */ }
}

// ————— The quiz —————
function QuizRun({ quizId, onFinish }) {
  const quiz = QUIZ[quizId];
  const kana = SECTIONS[quiz.section].kind === "kana";
  const [qs] = useState(() => buildQuestions(quizId));
  const [i, setI] = useState(0);
  const [picked, setPicked] = useState(null);
  const [right, setRight] = useState(0);
  const missed = useRef([]);
  const q = qs[i];

  useEffect(() => { if (kana) loadSprite().then(() => { if (q) say(q.item); }); }, [i]); // eslint-disable-line react-hooks/exhaustive-deps

  const pick = (opt) => {
    if (picked) return;
    setPicked(opt);
    if (opt === q.item.q) setRight((r) => r + 1);
    else missed.current.push(q.item.q);
  };
  const next = () => {
    if (i + 1 < qs.length) { setI(i + 1); setPicked(null); }
    else onFinish({ right, n: qs.length, missed: missed.current });
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
      <span style={{ font: `0.75rem ${T.uiFont}`, color: T.sub }}>{i + 1} of {qs.length}</span>
      {kana ? (
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10 }}>
          <span style={{ font: `700 1rem ${T.uiFont}` }}>Tap the kana you hear</span>
          <button className="ts-btn ts-btn-washi" onClick={() => say(q.item)} aria-label="Play the sound again">Play again</button>
        </div>
      ) : (
        <span style={{ font: `700 1rem/1.5 ${T.uiFont}` }}>Which kanji means “{q.item.meaning}”?</span>
      )}
      <div style={{ display: "grid", gridTemplateColumns: `repeat(${kana ? 3 : 2}, minmax(0, 1fr))`, gap: 10 }}>
        {q.options.map((opt) => {
          const isRight = picked && opt === q.item.q;
          const isWrongPick = picked === opt && opt !== q.item.q;
          return (
            <button key={opt} onClick={() => pick(opt)} lang="ja" disabled={!!picked && !isRight && !isWrongPick}
                    className="ts-tile" aria-label={opt}
                    style={{
                      minHeight: 64, font: `700 1.75rem ${T.jpFont}`,
                      ...(isRight ? { background: T.okBg, boxShadow: `inset 0 0 0 2.5px ${T.ok}, 0 3px 0 #CFC4A8` } : null),
                      ...(isWrongPick ? { boxShadow: `inset 0 0 0 2.5px ${T.ink}, 0 3px 0 #CFC4A8`, opacity: 0.75 } : null),
                    }}>
              {opt}
            </button>
          );
        })}
      </div>
      {picked && (
        <>
          <p style={body} role="status">
            {picked === q.item.q ? "Right." : <>It was <span lang="ja" style={{ font: `700 1.125rem ${T.jpFont}`, color: T.ink }}>{q.item.q}</span>.</>}
          </p>
          <button className="ts-btn ts-btn-shu" onClick={next}>{i + 1 < qs.length ? "Next" : "See how it went"}</button>
        </>
      )}
    </div>
  );
}

function Result({ quizId, res, onAgain, onClose }) {
  const quiz = QUIZ[quizId];
  const name = SECTIONS[quiz.section].name;
  const score = <span style={{ font: `700 1.5rem ${T.jpFont}`, color: T.ink }}>{res.right} of {res.n}</span>;
  const weak = res.weak.filter((w) => w.items.length);
  const weakList = weak.length > 0 && (
    <ul style={{ margin: 0, paddingLeft: 18, display: "flex", flexDirection: "column", gap: 4 }}>
      {weak.map((w) => (
        <li key={w.title} style={{ font: `0.875rem/1.6 ${T.uiFont}` }}>
          {w.title ? <strong>{w.title}</strong> : null}{w.title ? " — " : ""}
          <span lang="ja" style={{ font: `1.0625rem ${T.jpFont}` }}>{w.items.join("　")}</span>
        </li>
      ))}
    </ul>
  );
  if (res.passed) {
    const stage = !!quiz.requires;
    return (
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        {score}
        <p style={{ ...body, color: T.ink, fontWeight: 700 }}>Passed.</p>
        <p style={body}>
          {stage
            ? `The ${name} lessons this quiz covers are marked done, so you can start after them.`
            : res.stageOpen
              ? "That was the last group. The stage quiz is open now, at the top of this section."
              : "One group done. The others are waiting at the top of this section."}
        </p>
        <button className="ts-btn ts-btn-shu" onClick={onClose}>Done</button>
      </div>
    );
  }
  if (res.locked) {
    return (
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        {score}
        <p style={{ ...body, color: T.ink, fontWeight: 700 }}>Let's pause this quiz for a week.</p>
        <p style={body}>It opens again on {fmtDay(res.until)}. Until then, go back to the lessons in {name}, or review the parts that slipped:</p>
        {weakList}
        <button className="ts-btn ts-btn-shu" onClick={onClose}>Review in {name}</button>
      </div>
    );
  }
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
      {score}
      <p style={{ ...body, color: T.ink, fontWeight: 700 }}>Close — {passMark(res.n)} of {res.n} passes.</p>
      <p style={body}>Try again now, or look over these first:</p>
      {weakList}
      <button className="ts-btn ts-btn-shu" onClick={onAgain}>Try again</button>
      <button className="ts-btn ts-btn-washi" onClick={onClose}>Not now</button>
    </div>
  );
}

function QuizDialog({ quizId, onClose, onCredited }) {
  const [round, setRound] = useState(0);
  const [res, setRes] = useState(null);
  const finish = async (score) => {
    const r = await recordAttempt(quizId, score);
    const sec = QUIZ[quizId].section;
    const stageOpen = quizStatus(r.state, SECTIONS[sec].stage.id).state === "available";
    setRes({ ...r, ...score, stageOpen });
    if (r.credited) onCredited?.();
  };
  return (
    <Dialog label="Review quiz" onClose={onClose}>
      <span style={{ font: `700 1.125rem/1.35 ${T.uiFont}` }}>{QUIZ[quizId].title}</span>
      {res
        ? <Result quizId={quizId} res={res} onClose={onClose} onAgain={() => { setRes(null); setRound((x) => x + 1); }} />
        : <QuizRun key={round} quizId={quizId} onFinish={finish} />}
    </Dialog>
  );
}

// ————— The card at the top of a section —————
export function ReviewQuizCard({ section, onCredited }) {
  const [st, setSt] = useState(null);
  const [open, setOpen] = useState(null);
  const reload = useCallback(() => { readPlacement().then(setSt); }, []);
  useEffect(() => { reload(); }, [reload, section]);

  const sec = SECTIONS[section];
  if (!sec || !st || !sectionOffered(st, section)) return null;
  // Once the stage quiz is passed the card has done its job, and goes.
  if (quizStatus(st, sec.stage.id).state === "passed" && !open) return null;

  const row = (q) => {
    const s = quizStatus(st, q.id);
    const status = s.state === "passed" ? "Passed"
      : s.state === "locked" ? `Opens again ${fmtDay(s.until)}`
      : s.state === "waiting" ? "Opens once every group above is passed"
      : `${q.n} questions · ${passMark(q.n)} right to pass`;
    const can = s.state === "available";
    return (
      <button key={q.id} className="ts-card ts-card-btn" disabled={!can} onClick={() => can && setOpen(q.id)}
              style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", gap: 10,
                       padding: "12px 14px", cursor: can ? "pointer" : "default", opacity: s.state === "waiting" ? 0.7 : 1 }}>
        <span style={{ display: "flex", flexDirection: "column", gap: 2, minWidth: 0 }}>
          <span style={{ font: `700 0.9375rem ${T.uiFont}` }}>{q.requires ? `Stage quiz — ${q.title.toLowerCase()}` : q.title}</span>
          <span style={{ font: `0.8125rem ${T.uiFont}`, color: s.state === "passed" ? T.ok : T.sub }}>{status}</span>
        </span>
        {can && <span className="ts-btn ts-btn-wood" style={{ minHeight: 40, padding: "0 14px", fontSize: "0.875rem" }} aria-hidden="true">Start</span>}
      </button>
    );
  };

  return (
    <section aria-label={`${sec.name} review quiz`}
             style={{ maxWidth: 720, margin: "0 auto", padding: "16px 16px 0", boxSizing: "border-box",
                      display: "flex", flexDirection: "column", gap: 10 }}>
      <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
        <span style={{ ...LABEL, color: "var(--ts-on-tatami)" }}>REVIEW QUIZ</span>
        <p style={{ ...body, color: "var(--ts-on-tatami)" }}>
          You said you've studied {sec.name.toLowerCase()} before. Check where you are with a quiz for each group; pass them all and the stage quiz opens. Below {Math.round(0.6 * 100)}%, a quiz rests for {LOCK_DAYS === 7 ? "a week" : `${LOCK_DAYS} days`}.
        </p>
      </div>
      {sec.groups.map(row)}
      {row(sec.stage)}
      {open && <QuizDialog quizId={open} onClose={() => { setOpen(null); reload(); }} onCredited={onCredited} />}
    </section>
  );
}
